parameters.jsonBody:
={
  "model": "sonar-pro",
  "messages": [
    { "role": "system", "content": "Research competitors for this product and suggest unique selling points." },
    { "role": "user", "content": "{{ $json.body.product_name }}" }
  ]
}

parameters.text:
Research Data: {{ $node["Perplexity Research"].json.choices[0].message.content }}

Product Name: {{ $node["Webhook Trigger"].json.body.product_name }}

Generate the 5 ad angles now.

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "ad_variations": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "angle_name": {
            "type": "string",
            "description": "Short title of the marketing angle (e.g., Problem/Solution)."
          },
          "visual_prompt": {
            "type": "string",
            "description": "A highly detailed image prompt for Nano Banana Pro. Must include layout instructions based on the reference image."
          },
          "ad_copy": {
            "type": "string",
            "description": "The headline and body text for the Facebook/Instagram ad."
          }
        },
        "required": ["angle_name", "visual_prompt", "ad_copy"]
      }
    }
  },
  "required": ["ad_variations"]
}
